// M6 Android assets (STYLE-GUIDE 6h). One geometry → SVG masters, Android drop-in resources, drawn pictures.
// Run: node creative/m6/build.js [--png] [--shots]   (playwright with chromium resolvable, e.g. NODE_PATH)
//   (no flag)  writes SVGs + Android XML
//   --png      also renders the legacy mipmap PNGs (API 24–25) and the check sheets
// Edit geometry/copy here, never the generated files by hand.
const fs = require('fs');
const path = require('path');
const D = __dirname;
const C = { seal: '#9A3412', paper: '#FBF5EC', dot: '#FFD23F', night: '#14110E' };
const mk = (p) => { fs.mkdirSync(path.dirname(p), { recursive: true }); return p; };
const write = (rel, s) => fs.writeFileSync(mk(path.join(D, rel)), s);
const r2 = (n) => Math.round(n * 100) / 100;

// ── Glyph geometry (logo B, STYLE-GUIDE §0) as point lists on the 512 grid ──────────────────────
const MASTER = {
  strokes: [
    { pts: [[256, 96], [256, 204]], w: 56 },
    { pts: [[196, 128], [316, 128]], w: 50 },
    { pts: [[100, 216], [412, 216]], w: 50 },
    { pts: [[262, 292], [178, 408], [304, 396]], w: 56 },
  ],
  dot: [388, 392, 44],
  oy: 6, // optical centre 6 units below the geometric centre
};
// Notification geometry: the favicon pixel grid (64-unit strokes), dot pulled 8 units right and 4 up and
// shrunk to r44 so a 1.5 dp gap survives at 24 dp (at r48 it merges with the path's end at mdpi).
const NOTIF = {
  strokes: [
    { pts: [[256, 64], [256, 192]], w: 64 },
    { pts: [[192, 96], [320, 96]], w: 64 },
    { pts: [[96, 192], [416, 192]], w: 64 },
    { pts: [[256, 288], [160, 416], [288, 416]], w: 64 },
  ],
  dot: [392, 404, 44],
  cx: 256, cy: 240, // bbox centre (x 64–448, y 32–448)
};
// place a glyph: point (cx,cy) of the 512 grid lands on (ox,oy), k = output units per grid unit
function place(g, ox, oy, k, cx = 256, cy = 256) {
  const f = ([x, y]) => [r2(ox + (x - cx) * k), r2(oy + (y - cy) * k)];
  return {
    strokes: g.strokes.map((s) => ({ pts: s.pts.map(f), w: r2(s.w * k) })),
    dot: [...f(g.dot), r2(g.dot[2] * k)],
  };
}
const d = (pts) => pts.map((p, i) => `${i ? 'L' : 'M'}${p[0]} ${p[1]}`).join('');
const circ = (cx, cy, r) => `M${r2(cx - r)} ${cy}a${r} ${r} 0 1 0 ${r2(2 * r)} 0a${r} ${r} 0 1 0 ${r2(-2 * r)} 0z`;
const rrect = (x, y, w, h, r) =>
  `M${r2(x + r)} ${y}H${r2(x + w - r)}A${r} ${r} 0 0 1 ${r2(x + w)} ${r2(y + r)}V${r2(y + h - r)}A${r} ${r} 0 0 1 ${r2(x + w - r)} ${r2(y + h)}H${r2(x + r)}A${r} ${r} 0 0 1 ${x} ${r2(y + h - r)}V${r2(y + r)}A${r} ${r} 0 0 1 ${r2(x + r)} ${y}z`;
function glyphSvg(p, ink, dot) {
  return p.strokes.map((s) => `<path d="${d(s.pts)}" fill="none" stroke="${ink}" stroke-width="${s.w}" stroke-linecap="round" stroke-linejoin="round"/>`).join('\n  ')
    + `\n  <circle cx="${p.dot[0]}" cy="${p.dot[1]}" r="${p.dot[2]}" fill="${dot}"/>`;
}
function glyphVd(p, ink, dot) {
  return p.strokes.map((s) => `  <path android:pathData="${d(s.pts)}" android:strokeColor="${ink}" android:strokeWidth="${s.w}" android:strokeLineCap="round" android:strokeLineJoin="round"/>`).join('\n')
    + `\n  <path android:pathData="${circ(...p.dot)}" android:fillColor="${dot}"/>`;
}
const svgDoc = (vb, label, inner) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${vb} ${vb}" width="${vb}" height="${vb}" role="img" aria-label="${label}">\n  <title>${label}</title>\n  ${inner}\n</svg>\n`;
const vdDoc = (dp, vp, inner) => `<?xml version="1.0" encoding="utf-8"?>\n<!-- Generated by creative/m6/build.js (STYLE-GUIDE 6h.1). Do not edit by hand. -->\n<vector xmlns:android="http://schemas.android.com/apk/res/android"\n  android:width="${dp}dp" android:height="${dp}dp"\n  android:viewportWidth="${vp}" android:viewportHeight="${vp}">\n${inner}\n</vector>\n`;

// ── 1. Adaptive icon (108 dp canvas, 72 dp visible, 66 dp safe circle) ─────────────────────────
const FG_K = 0.112; // glyph 40.5 dp wide (56 % of the visible 72 dp); farthest ink 26.9 dp from centre (safe r 33)
const FG = place(MASTER, 54, 54 + MASTER.oy * (108 / 512), FG_K);
write('icon/ic_launcher_foreground.svg', svgDoc(108, '怎么去? adaptive icon foreground', glyphSvg(FG, C.paper, C.dot)));
write('icon/ic_launcher_background.svg', svgDoc(108, '怎么去? adaptive icon background', `<rect width="108" height="108" fill="${C.seal}"/>`));
write('icon/ic_launcher_monochrome.svg', svgDoc(108, '怎么去? themed icon (monochrome)', glyphSvg(FG, '#FFFFFF', '#FFFFFF')));
// reference composite (what a circle-mask launcher shows), for docs only
write('icon/ic_launcher_preview.svg', svgDoc(108, '怎么去? adaptive icon, composite', `<defs><clipPath id="m"><circle cx="54" cy="54" r="36"/></clipPath></defs><g clip-path="url(#m)"><rect width="108" height="108" fill="${C.seal}"/>\n  ${glyphSvg(FG, C.paper, C.dot)}</g>`));

// ── 2. Notification small icon (24 dp, alpha only) ─────────────────────────────────────────────
const NI = place(NOTIF, 12, 12, 22 / 416, NOTIF.cx, NOTIF.cy);
write('icon/ic_stat_trip.svg', svgDoc(24, '怎么去? notification icon', glyphSvg(NI, '#FFFFFF', '#FFFFFF')));

// ── 3. Splash icon (Android 12 SplashScreen / core-splashscreen: 288 dp, content inside the 192 dp circle) ─
// The 'any' app icon (seal + chop frame + glyph at 84 %) at 144 dp, centred. Farthest corner 88.8 dp < 96.
const SP = { x: 72, s: 144 };
const spk = SP.s / 512;
const SPG = place(MASTER, 144, 144 + MASTER.oy * spk, 0.84 * spk);
const spFrame = { x: r2(72 + 40 * spk), w: r2(432 * spk), r: r2(80 * spk), sw: r2(12 * spk) };
write('icon/splash_icon.svg', svgDoc(288, '怎么去? splash icon',
  `<rect x="72" y="72" width="144" height="144" rx="${r2(112 * spk)}" fill="${C.seal}"/>\n  <rect x="${spFrame.x}" y="${spFrame.x}" width="${spFrame.w}" height="${spFrame.w}" rx="${spFrame.r}" fill="none" stroke="${C.paper}" stroke-width="${spFrame.sw}" opacity=".9"/>\n  ${glyphSvg(SPG, C.paper, C.dot)}`));

// ── 4. Android drop-in resources (copy creative/m6/android-res/* over src/android/android/app/src/main/res/) ─
const R = 'android-res/';
write(R + 'drawable/ic_launcher_foreground.xml', vdDoc(108, 108, glyphVd(FG, '#FFFBF5EC', '#FFFFD23F')));
write(R + 'drawable/ic_launcher_monochrome.xml', vdDoc(108, 108, glyphVd(FG, '#FFFFFFFF', '#FFFFFFFF')));
write(R + 'drawable/ic_stat_trip.xml', vdDoc(24, 24, glyphVd(NI, '#FFFFFFFF', '#FFFFFFFF')));
write(R + 'drawable/splash_icon.xml', vdDoc(288, 288,
  `  <path android:pathData="${rrect(72, 72, 144, 144, r2(112 * spk))}" android:fillColor="#FF9A3412"/>\n  <path android:pathData="${rrect(spFrame.x, spFrame.x, spFrame.w, spFrame.w, spFrame.r)}" android:strokeColor="#FFFBF5EC" android:strokeAlpha="0.9" android:strokeWidth="${spFrame.sw}"/>\n${glyphVd(SPG, '#FFFBF5EC', '#FFFFD23F')}`));
const adaptive = `<?xml version="1.0" encoding="utf-8"?>\n<!-- STYLE-GUIDE 6h.1: logo B adaptive icon with a monochrome layer for themed icons (Android 13+). -->\n<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n    <background android:drawable="@color/ic_launcher_background"/>\n    <foreground android:drawable="@drawable/ic_launcher_foreground"/>\n    <monochrome android:drawable="@drawable/ic_launcher_monochrome"/>\n</adaptive-icon>\n`;
write(R + 'mipmap-anydpi-v26/ic_launcher.xml', adaptive);
write(R + 'mipmap-anydpi-v26/ic_launcher_round.xml', adaptive);
write(R + 'values/ic_launcher_background.xml', `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <!-- c-primary (light), the seal. Same in dark mode: the seal is a solid object (STYLE-GUIDE §0). -->\n    <color name="ic_launcher_background">#9A3412</color>\n</resources>\n`);
write(R + 'values/splash.xml', `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <!-- c-canvas light: warm paper (STYLE-GUIDE 6h.1 splash) -->\n    <color name="splash_background">#FBF5EC</color>\n    <!-- notification accent: c-primary light (small icon tint in the shade header) -->\n    <color name="notification_accent">#9A3412</color>\n</resources>\n`);
write(R + 'values-night/splash.xml', `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <!-- c-canvas dark: warm charcoal -->\n    <color name="splash_background">#14110E</color>\n    <color name="notification_accent">#9A3412</color>\n</resources>\n`);
write(R + 'README.txt', `STYLE-GUIDE 6h.1 drop-in resources (generated by creative/m6/build.js).
Copy over src/android/android/app/src/main/res/, then:
- delete mipmap-*/ic_launcher_foreground.png and drawable-v24/ic_launcher_foreground.xml (Capacitor template),
  drawable/ic_launcher_background.xml, drawable/splash.png and drawable-port-*/drawable-land-* splash.png;
- styles.xml, AppTheme.NoActionBarLaunch (parent Theme.SplashScreen), replace android:background with:
    <item name="windowSplashScreenBackground">@color/splash_background</item>
    <item name="windowSplashScreenAnimatedIcon">@drawable/splash_icon</item>
    <item name="postSplashScreenTheme">@style/AppTheme.NoActionBar</item>
- NotificationCompat.Builder: setSmallIcon(R.drawable.ic_stat_trip) (already), setColor(getColor(R.color.notification_accent)).
mipmap-<density>/ic_launcher.png and ic_launcher_round.png are the API 24–25 fallbacks (rendered with --png).
`);

// ── 5. Drawn pictures (battery guide, permissions, install) ─────────────────────────────────────
// Same visual language as creative/m5/install (classes ig-*, token vars with light fallbacks): inline them so
// they follow dark mode. Text carries the meaning; pictures are aria-hidden. Saffron ring = "tap here".
const FONT = `"Atkinson Hyperlegible","PingFang SC","Hiragino Sans GB","Noto Sans CJK SC","Noto Sans SC","Microsoft YaHei",system-ui,sans-serif`;
const STYLE = `<style>.ig-surf{fill:var(--c-surface,#FFFFFF);stroke:var(--c-line,#D9CBB6);stroke-width:2}.ig-quiet{fill:var(--c-surface-2,#F3EADC)}.ig-bar{fill:var(--c-line,#D9CBB6)}.ig-rule{stroke:var(--c-line,#D9CBB6);stroke-width:2}.ig-glyph{fill:none;stroke:var(--c-ink-2,#4A4038);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}.ig-hi{fill:var(--c-saffron-soft,#FFF1C2);stroke:#FFD23F;stroke-width:4}.ig-text{fill:var(--c-ink,#1D1915);font:700 15px ${FONT}}.ig-sub{fill:var(--c-ink-2,#4A4038);font:400 13px ${FONT}}.ig-title{fill:var(--c-ink,#1D1915);font:700 16px ${FONT}}.ig-on{fill:var(--c-jade,#0E5B49)}.ig-off{fill:var(--c-line,#D9CBB6)}.ig-knob{fill:var(--c-surface,#FFFFFF)}.ig-ring{fill:none;stroke:var(--c-ink-2,#4A4038);stroke-width:2.4}.ig-pick{fill:var(--c-ink,#1D1915)}.ig-dim{fill:var(--c-ink,#1D1915);opacity:.14}.ig-btn{fill:var(--c-surface-2,#F3EADC)}</style>`;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// rough advance widths for wrapping at 15 px bold (CJK full width; Latin ~0.55 em)
const tw = (s, px = 15) => [...s].reduce((a, ch) => a + (/[⺀-￿]/.test(ch) ? px : /[A-Z0-9]/.test(ch) ? px * 0.62 : px * 0.53), 0);
function wrap(s, max, px = 15) {
  const cjk = /[⺀-￿]/.test(s) && !/ /.test(s);
  const parts = cjk ? [...s] : s.split(/(?<= )/);
  const lines = [''];
  for (const p of parts) {
    const cur = lines[lines.length - 1];
    if (cur && tw(cur + p, px) > max && !/^[。，、？！：；”）]/.test(p)) lines.push(p.trimStart()); else lines[lines.length - 1] = cur + p;
  }
  return lines.map((l) => l.trimEnd());
}
const textLines = (lines, x, y, cls = 'ig-text', lh = 19, anchor = '') =>
  lines.map((l, i) => `<text class="${cls}" x="${x}" y="${y + i * lh}"${anchor ? ` text-anchor="${anchor}"` : ''}>${esc(l)}</text>`).join('');
const seal = (x, y, s) => `<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${r2(s * 0.22)}" fill="${C.seal}"/><g transform="translate(${x} ${y}) scale(${r2(s / 512 * 1000) / 1000})">${glyphSvg(place(MASTER, 256, 262, 0.8), C.paper, C.dot)}</g>`;
const sw = (x, y, on, hi) => `${hi ? `<rect class="ig-hi" x="${x - 7}" y="${y - 7}" width="58" height="40" rx="20"/>` : ''}<rect class="${on ? 'ig-on' : 'ig-off'}" x="${x}" y="${y + 3}" width="44" height="20" rx="10"/><circle class="ig-knob" cx="${on ? x + 34 : x + 10}" cy="${y + 13}" r="7"/>`;
const W = 280;
const svgPic = (h, inner) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${h}" width="${W}" height="${h}" aria-hidden="true" focusable="false">\n${STYLE}\n${inner}\n</svg>\n`;

/** A settings page: back arrow + title, optional app header, rows (row | radio | switch | head), saffron ring on hi rows. */
function screen({ title, app, rows, note }) {
  let y = 8, out = '';
  const x0 = 20, w = 240, inner = 196;
  out += `<path class="ig-glyph" d="M38 ${y + 20}l-7 7 7 7"/>` + textLines([title], 52, y + 32, 'ig-title');
  y += 50;
  if (app) { out += seal(36, y, 34) + textLines(['怎么去?'], 82, y + 23); y += 48; out += `<path class="ig-rule" d="M${x0} ${y}h${w}"/>`; y += 4; }
  for (const r of rows) {
    if (r.type === 'head') { out += textLines([r.t], 36, y + 20, 'ig-sub'); y += 28; continue; }
    const tx = r.type === 'radio' ? 64 : 36;
    const max = r.type === 'switch' ? inner - 52 : inner - (tx - 36);
    const lines = wrap(r.t, max);
    const sub = r.sub ? wrap(r.sub, max, 13) : [];
    const h = Math.max(44, 14 + lines.length * 19 + sub.length * 16 + 10);
    if (r.hi && r.type !== 'switch') out += `<rect class="ig-hi" x="${x0 + 6}" y="${y + 3}" width="${w - 12}" height="${h - 6}" rx="12"/>`;
    if (r.type === 'radio') out += `<circle class="ig-ring" cx="44" cy="${y + h / 2}" r="9"/>${r.on ? `<circle class="ig-pick" cx="44" cy="${y + h / 2}" r="4.5"/>` : ''}`;
    if (r.type === 'switch') out += sw(206, y + h / 2 - 13, r.on, r.hi);
    if (r.type === 'row' && r.chev !== false) out += `<path class="ig-glyph" d="M236 ${y + h / 2 - 6}l6 6-6 6"/>`;
    const ty = y + (h - (lines.length * 19 + sub.length * 16)) / 2 + 14;
    out += textLines(lines, tx, ty) + textLines(sub, tx, ty + lines.length * 19 - 2, 'ig-sub', 16);
    y += h;
  }
  if (note) { y += 4; out += textLines(wrap(note, inner, 13), 36, y + 14, 'ig-sub', 16); y += 16 * wrap(note, inner, 13).length + 4; }
  y += 10;
  return svgPic(y + 8, `<rect class="ig-surf" x="${x0}" y="4" width="${w}" height="${y}" rx="18"/>\n${out}`);
}

/** A system dialog over a dimmed screen: optional app seal, title, body, option rows, buttons (stacked or side by side). */
function dialog({ title, body, opts = [], buttons, stack, appIcon = true }) {
  let y = 34, out = '';
  const x0 = 34, w = 212, inner = 180;
  if (appIcon) { out += seal(W / 2 - 16, y, 32); y += 44; }
  const tl = wrap(title, inner, 16);
  out += textLines(tl, W / 2, y + 14, 'ig-title', 21, 'middle'); y += tl.length * 21 + 6;
  if (body) { const bl = wrap(body, inner, 13); out += textLines(bl, W / 2, y + 12, 'ig-sub', 16, 'middle'); y += bl.length * 16 + 8; }
  for (const o of opts) {
    out += `<rect class="ig-quiet" x="${x0 + 14}" y="${y}" width="${w - 28}" height="34" rx="10"/>${o.on ? `<circle class="ig-pick" cx="${x0 + 32}" cy="${y + 17}" r="5"/>` : `<circle class="ig-ring" cx="${x0 + 32}" cy="${y + 17}" r="7"/>`}` + textLines([o.t], x0 + 46, y + 22);
    y += 40;
  }
  y += 4;
  if (stack) {
    for (const b of buttons) {
      const bl = wrap(b.t, inner - 16);
      const h = 14 + bl.length * 19 + 6;
      out += `<rect class="${b.hi ? 'ig-hi' : 'ig-btn'}" x="${x0 + 12}" y="${y}" width="${w - 24}" height="${h}" rx="${h / 2 > 18 ? 18 : h / 2}"/>` + textLines(bl, W / 2, y + 21, 'ig-text', 19, 'middle');
      y += h + 8;
    }
  } else {
    const bw = (w - 36) / buttons.length;
    buttons.forEach((b, i) => {
      const bx = x0 + 12 + i * (bw + 12);
      out += `<rect class="${b.hi ? 'ig-hi' : 'ig-btn'}" x="${bx}" y="${y}" width="${bw}" height="36" rx="18"/>` + textLines([b.t], bx + bw / 2, y + 23, 'ig-text', 19, 'middle');
    });
    y += 44;
  }
  const h = y + 8;
  return svgPic(h + 34, `<rect class="ig-surf" x="20" y="4" width="240" height="${h + 26}" rx="18"/><rect class="ig-dim" x="21" y="5" width="238" height="${h + 24}" rx="17"/>\n<rect class="ig-surf" x="${x0}" y="22" width="${w}" height="${h - 10}" rx="22"/>\n${out}`);
}

/** Chrome: a bar at the bottom of a page (download prompt / finished). */
function browserBar({ file, line, btn }) {
  const fl = wrap(line, 170, 13);
  const bw = Math.max(64, tw(btn) + 28);
  const by = 112, h = 34 + fl.length * 16 + 44;
  return svgPic(by + h + 24, `<rect class="ig-surf" x="20" y="4" width="240" height="${by + h + 14}" rx="18"/>
<rect class="ig-quiet" x="34" y="18" width="212" height="28" rx="14"/><rect class="ig-bar" x="48" y="29" width="120" height="6" rx="3"/>
<rect class="ig-bar" x="40" y="62" width="160" height="8" rx="4"/><rect class="ig-bar" x="40" y="80" width="190" height="8" rx="4"/><rect class="ig-bar" x="40" y="98" width="120" height="8" rx="4"/>
<rect class="ig-surf" x="28" y="${by}" width="224" height="${h}" rx="14"/>
<path class="ig-glyph" d="M46 ${by + 12}v12M41 ${by + 19}l5 5 5-5M40 ${by + 29}h12"/>
${textLines([file], 62, by + 24, 'ig-text')}${textLines(fl, 62, by + 42, 'ig-sub', 16)}
<rect class="ig-hi" x="${238 - bw}" y="${by + h - 40}" width="${bw}" height="32" rx="16"/>
${textLines([btn], 238 - bw / 2, by + h - 19, 'ig-text', 19, 'middle')}`);
}

const PIC = {}; // name → { zh, en } svg
const both = (name, f) => { PIC[name] = { zh: f('zh'), en: f('en') }; };
const L = (lang, zh, en) => (lang === 'zh' ? zh : en);
const APPINFO = (l) => L(l, '应用信息', 'App info');

// Battery guide (6h.4). Menu names as of One UI 6–7, HyperOS 1–2, ColorOS 14–15, OriginOS 4–5, EMUI 12 / HarmonyOS 4 / MagicOS 8, Android 14–15 Pixel.
both('bg-google-1', (l) => screen({ title: APPINFO(l), app: true, rows: [
  { t: L(l, '通知', 'Notifications'), type: 'row' }, { t: L(l, '权限', 'Permissions'), type: 'row' },
  { t: L(l, '应用的电池用量', 'App battery usage'), type: 'row', hi: true }, { t: L(l, '存储和缓存', 'Storage & cache'), type: 'row' }] }));
both('bg-google-2', (l) => screen({ title: L(l, '应用的电池用量', 'App battery usage'), rows: [
  { t: L(l, '允许后台使用', 'Allow background usage'), type: 'switch', on: true, hi: true },
  { t: L(l, '不受限制', 'Unrestricted'), type: 'radio', on: true, hi: true }, { t: L(l, '已优化', 'Optimised'), type: 'radio' }] }));
both('bg-samsung-1', (l) => screen({ title: L(l, '应用程序信息', 'App info'), app: true, rows: [
  { t: L(l, '通知', 'Notifications'), type: 'row' }, { t: L(l, '权限', 'Permissions'), type: 'row' },
  { t: L(l, '电池', 'Battery'), type: 'row', hi: true }, { t: L(l, '存储', 'Storage'), type: 'row' }] }));
both('bg-samsung-2', (l) => screen({ title: L(l, '电池', 'Battery'), rows: [
  { t: L(l, '不受限制', 'Unrestricted'), type: 'radio', on: true, hi: true }, { t: L(l, '已优化', 'Optimised'), type: 'radio' }, { t: L(l, '受限制', 'Restricted'), type: 'radio' }] }));
both('bg-xiaomi-1', (l) => screen({ title: APPINFO(l), app: true, rows: [
  { t: L(l, '自启动', 'Autostart'), type: 'switch', on: false }, { t: L(l, '省电策略', 'Battery saver'), type: 'row', hi: true }, { t: L(l, '通知管理', 'Notifications'), type: 'row' }] }));
both('bg-xiaomi-2', (l) => screen({ title: L(l, '省电策略', 'Battery saver'), rows: [
  { t: L(l, '无限制', 'No restrictions'), type: 'radio', on: true, hi: true }, { t: L(l, '智能限制后台运行', 'Battery saver (recommended)'), type: 'radio' }, { t: L(l, '限制后台运行', 'Restrict background apps'), type: 'radio' }] }));
both('bg-xiaomi-3', (l) => screen({ title: APPINFO(l), app: true, rows: [
  { t: L(l, '自启动', 'Autostart'), type: 'switch', on: true, hi: true }, { t: L(l, '省电策略', 'Battery saver'), type: 'row', sub: L(l, '无限制', 'No restrictions') }, { t: L(l, '通知管理', 'Notifications'), type: 'row' }] }));
both('bg-oppo-1', (l) => screen({ title: APPINFO(l), app: true, rows: [
  { t: L(l, '通知管理', 'Notifications'), type: 'row' }, { t: L(l, '权限', 'Permissions'), type: 'row' },
  { t: L(l, '耗电管理', 'Battery usage'), type: 'row', hi: true }, { t: L(l, '存储占用', 'Storage usage'), type: 'row' }] }));
