both('perm-notify', (l) => dialog({ title: L(l, '要允许"怎么去"向你发送通知吗？', 'Allow 怎么去 to send you notifications?'), stack: true,
  buttons: [{ t: L(l, '允许', 'Allow'), hi: true }, { t: L(l, '不允许', 'Don\'t allow') }] }));
both('perm-settings-location', (l) => screen({ title: L(l, '位置信息权限', 'Location permission'), rows: [
  { t: L(l, '仅在使用该应用时允许', 'Allow only while using the app'), type: 'radio', on: true, hi: true },
  { t: L(l, '每次都询问', 'Ask every time'), type: 'radio' }, { t: L(l, '不允许', 'Don\'t allow'), type: 'radio' },
  { t: L(l, '使用确切位置', 'Use precise location'), type: 'switch', on: true, hi: true }] }));
both('perm-dnd', (l) => screen({ title: L(l, '下车提醒', 'Get-off alerts'), rows: [
  { t: L(l, '显示通知', 'Show notifications'), type: 'switch', on: true }, { t: L(l, '声音', 'Sound'), type: 'row', sub: L(l, '默认', 'Default') },
  { t: L(l, '覆盖"勿扰"', 'Override Do Not Disturb'), type: 'switch', on: true, hi: true }], note: L(l, '三星手机叫"忽略勿扰模式"。', 'On Samsung it says "Ignore Do not disturb".') }));
both('perm-tts', (l) => screen({ title: L(l, '安装语音数据', 'Install voice data'), rows: [
  { t: L(l, '中文（中国）', 'Chinese (China)'), type: 'row', hi: true, sub: L(l, '按一下下载', 'Tap to download'), chev: false },
  { t: L(l, '英语（英国）', 'English (UK)'), type: 'row', sub: L(l, '已安装', 'Installed'), chev: false }, { t: L(l, '粤语（香港）', 'Cantonese (Hong Kong)'), type: 'row', chev: false }] }));

// Install and update (6h.9, /android page).
both('install-1-warn', (l) => browserBar({ file: 'howtogo-1.0.1.apk', line: L(l, '这类文件可能会损害你的设备。仍要下载吗？', 'This type of file can harm your device. Download anyway?'), btn: L(l, '仍然下载', 'Download anyway') }));
