both('install-3-source', (l) => screen({ title: L(l, '安装未知应用', 'Install unknown apps'), rows: [
  { t: 'Chrome', type: 'head' }, { t: L(l, '允许来自此来源的应用', 'Allow from this source'), type: 'switch', on: true, hi: true }],
  note: L(l, '手机先问时，按"设置"就会来到这里。打开后按返回。', 'When your phone asks first, tap "Settings" to come here. Turn it on, then go back.') }));
both('install-4-install', (l) => dialog({ title: '怎么去', body: L(l, '要安装此应用吗？', 'Do you want to install this app?'), buttons: [{ t: L(l, '取消', 'Cancel') }, { t: L(l, '安装', 'Install'), hi: true }] }));
both('install-5-protect', (l) => dialog({ appIcon: false, title: L(l, 'Play 保护机制', 'Play Protect'), body: L(l, '建议扫描这个应用', 'App scan recommended'), stack: true,
  buttons: [{ t: L(l, '扫描应用', 'Scan app'), hi: true }, { t: L(l, '仍然安装', 'Install anyway') }] }));
both('install-6-done', (l) => dialog({ title: '怎么去', body: L(l, '已安装应用。', 'App installed.'), buttons: [{ t: L(l, '完成', 'Done') }, { t: L(l, '打开', 'Open'), hi: true }] }));
both('update-1', (l) => dialog({ title: '怎么去', body: L(l, '要更新此应用吗？你的资料会保留。', 'Do you want to update this app? Your data will be kept.'), buttons: [{ t: L(l, '取消', 'Cancel') }, { t: L(l, '更新', 'Update'), hi: true }] }));

for (const [name, v] of Object.entries(PIC)) for (const l of ['zh', 'en']) write(`pictures/${name}-${l}.svg`, v[l]);

// ── 6. New icons (Director approval, 6h.11): §1.4 rules ───────────────────────────────────────
write('icons.svg', `<svg xmlns="http://www.w3.org/2000/svg" style="display:none">
  <!-- M6 icons (STYLE-GUIDE 6h.11). Same rules as §1.4: 24 grid, 2.2 stroke, round caps/joins, currentColor, no fill. -->
  <!-- battery: battery guide, Settings row, the H5 "phone closed the app" note. A horizontal cell with one bar. -->
  <symbol id="i-battery" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="7.5" width="16" height="9" rx="2"/><path d="M21.5 10.5v3M6.5 10.5v3M9.5 10.5v3"/></symbol>
  <!-- bell-off: notifications are off (H5 note, Settings). The §1.4 bell with one slash. -->
  <symbol id="i-bell-off" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.2 6.4A6 6 0 0 1 18 11v4.2M18 18H4.5L6 16v-5c0-.6.1-1.2.3-1.8"/><path d="M10 20.5a2 2 0 0 0 4 0"/><path d="M3.5 3.5l17 17"/></symbol>
  <!-- smartphone: the Android app (Get-the-app card, update notice, /android requirements, WebView screen). A phone with the saffron-dot idea as a filled dot. -->
  <symbol id="i-smartphone" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="6.5" y="2.5" width="11" height="19" rx="2.5"/><path d="M10.5 18.5h3"/></symbol>
</svg>
`);

if (!process.argv.includes('--png')) { console.log('SVG + XML written. Add --png for PNGs and check sheets.'); process.exit(0); }

// ── 7. PNG renders and check sheets (Playwright) ─────────────────────────────────────────────
(async () => {
  const { chromium } = require('playwright');
  const b = await chromium.launch();
  const p = await b.newPage({ deviceScaleFactor: 1 });
  const read = (f) => fs.readFileSync(path.join(D, f), 'utf8');
  const logo = (f) => fs.readFileSync(path.join(D, '..', 'logo', 'final', f), 'utf8');
  const shot = async (svg, size, out, clip) => {
    await p.setViewportSize({ width: size, height: size });
    await p.setContent(`<style>html,body{margin:0;background:transparent}svg{display:block;width:${size}px;height:${size}px${clip ? `;clip-path:${clip}` : ''}}</style>${svg}`);
    await p.screenshot({ path: mk(path.join(D, out)), omitBackground: true });
  };
  // legacy launcher PNGs (API 24–25 only; 26+ uses the adaptive XML). ≤ 48 px uses the favicon pixel geometry (§0).
  const dens = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };
  const roundSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><circle cx="256" cy="256" r="256" fill="${C.seal}"/><g transform="translate(256 262) scale(0.74) translate(-256 -256)">${glyphSvg(place(MASTER, 256, 256, 1), C.paper, C.dot)}</g></svg>`;
  for (const [dn, px] of Object.entries(dens)) {
    await shot(px <= 48 ? logo('favicon.svg') : logo('icon.svg'), px, `${R}mipmap-${dn}/ic_launcher.png`);
    await shot(roundSvg, px, `${R}mipmap-${dn}/ic_launcher_round.png`);
  }

  // Check sheet 1: launcher at 48/72/96/192 px under 4 OEM masks, themed (mono) light/dark, splash light/dark.
  const fg = read('icon/ic_launcher_foreground.svg'), bg = read('icon/ic_launcher_background.svg'), mono = read('icon/ic_launcher_monochrome.svg');
  const layer = (mask, px, themed, dark) => {
    // the 108 canvas is shown through a 72/108 window, as the launcher does
    const s = px * 108 / 72, off = -(s - px) / 2;
    const bgFill = themed ? (dark ? '#3B2F2A' : '#F6DDD3') : null;
    const ink = themed ? (dark ? '#FFB59A' : '#7A2E12') : null;
    const m = mono.replace(/#FFFFFF/g, ink || '#FFFFFF');
    return `<div class="ic ${mask}" style="width:${px}px;height:${px}px">${themed ? `<div style="position:absolute;inset:0;background:${bgFill}"></div>` : `<div class="l" style="width:${s}px;height:${s}px;left:${off}px;top:${off}px">${bg}</div>`}<div class="l" style="width:${s}px;height:${s}px;left:${off}px;top:${off}px">${themed ? m : fg}</div></div>`;
  };
  const masks = ['circle', 'squircle', 'rounded', 'teardrop'];
  const sizes = [48, 72, 96, 192];
  const row = (title, themed, dark, wall) => `<section style="background:${wall}"><h2 style="color:${dark ? '#F6EEE4' : '#1D1915'}">${title}</h2>${masks.map((m) => `<div class="grp">${sizes.map((s) => layer(m, s, themed, dark)).join('')}<span style="color:${dark ? '#CFC3B5' : '#4A4038'}">${m}</span></div>`).join('')}</section>`;
  const splash = (dark) => `<div class="splash" style="background:${dark ? C.night : C.paper}"><div style="width:180px;height:180px">${read('icon/splash_icon.svg')}</div><div class="safe"></div></div>`;
  await p.setViewportSize({ width: 1500, height: 900 });
  await p.setContent(`<style>body{margin:0;font:14px system-ui}section{padding:16px 24px;display:flex;flex-wrap:wrap;gap:22px;align-items:flex-end}h2{width:100%;margin:0;font-size:15px}
    .grp{display:flex;gap:14px;align-items:flex-end}.grp span{font-size:12px;width:56px}
    .ic{position:relative;overflow:hidden}.ic .l{position:absolute}.ic svg{width:100%;height:100%;display:block}
    .circle{border-radius:50%}.squircle{border-radius:30%}.rounded{border-radius:16%}.teardrop{border-radius:50% 50% 50% 12%}
    .splash{position:relative;width:240px;height:240px;display:grid;place-items:center}.splash svg{width:100%;height:100%}
    .safe{position:absolute;width:120px;height:120px;border:1px dashed rgba(127,127,127,.6);border-radius:50%;left:60px;top:60px}</style>
    ${row('Adaptive icon · 48 / 72 / 96 / 192 px · OEM masks', false, false, '#FBF5EC')}
    ${row('On a dark wallpaper', false, true, '#14110E')}
    ${row('Themed icon (Android 13+, monochrome layer tinted by the system) · light', true, false, '#EFE7E1')}
    ${row('Themed icon · dark', true, true, '#1E1A18')}
    <section style="background:#ddd"><h2>Splash (Android 12 SplashScreen, 288 dp shown at 240 px; dashed = 192 dp mask circle) · light / dark</h2>${splash(false)}${splash(true)}</section>`);
  await p.screenshot({ path: path.join(D, 'shots/check-launcher.png'), fullPage: true });

  // Check sheet 2: notification small icon at 24 dp × 1, 1.5, 2, 3 (24/36/48/72 px) on light and dark status bars,
  // in the shade header with the accent tint, and 8× pixel zoom of mdpi/xhdpi renders.
  await shot(read('icon/ic_stat_trip.svg').replace(/#FFFFFF/g, '#000000'), 24, 'shots/_n24.png');
  await shot(read('icon/ic_stat_trip.svg').replace(/#FFFFFF/g, '#000000'), 48, 'shots/_n48.png');
  const n = read('icon/ic_stat_trip.svg');
  const tint = (col) => n.replace(/#FFFFFF/g, col);
  const img = (f) => 'data:image/png;base64,' + fs.readFileSync(path.join(D, f)).toString('base64');
  const bar = (bgc, col, label) => `<div class="bar" style="background:${bgc};color:${col}"><b>9:41</b>${[24, 36, 48, 72].map((s) => `<span style="width:${s}px;height:${s}px">${tint(col)}</span>`).join('')}<em>${label}</em></div>`;
  await p.setViewportSize({ width: 1100, height: 600 });
  await p.setContent(`<style>body{margin:0;font:14px system-ui}.bar{display:flex;gap:22px;align-items:center;padding:14px 24px}.bar svg{width:100%;height:100%;display:block}.bar span{display:block}em{font-style:normal;opacity:.7}
    .shade{display:flex;gap:12px;align-items:center;padding:16px 24px;background:#F3EFEA}.shade span.i{width:24px;height:24px;display:block}.shade svg{width:100%;height:100%}
    .zoom{display:flex;gap:28px;padding:20px 24px;background:#fff;align-items:flex-end}.zoom img{image-rendering:pixelated}</style>
    ${bar('#FBF5EC', '#1D1915', 'light status bar · 24 / 36 / 48 / 72 px')}${bar('#000000', '#FFFFFF', 'dark status bar')}${bar('#9A3412', '#FFFFFF', 'over a persimmon app top band')}
    <div class="shade"><span class="i">${tint('#9A3412')}</span><b style="color:#9A3412">怎么去</b><span style="color:#4A4038">· 行程进行中</span></div>
    <div class="shade" style="background:#2B2622"><span class="i">${tint('#FF9466')}</span><b style="color:#FF9466">怎么去</b><span style="color:#CFC3B5">· 行程进行中 (dark shade: system lightens the accent)</span></div>
    <div class="zoom"><img src="${img('shots/_n24.png')}" style="width:192px"><img src="${img('shots/_n48.png')}" style="width:192px"><span>mdpi 24 px and xhdpi 48 px renders at 8× / 4× (gaps survive)</span></div>`);
  await p.screenshot({ path: path.join(D, 'shots/check-notification.png'), fullPage: true });
  fs.unlinkSync(path.join(D, 'shots/_n24.png')); fs.unlinkSync(path.join(D, 'shots/_n48.png'));

  // Check sheet 3: every picture, light and dark tokens, at 1× (they're shown at max-width 280 in the app).
  const darkVars = '--c-canvas:#14110E;--c-surface:#1F1A16;--c-surface-2:#2A231D;--c-line:#43392F;--c-ink:#F6EEE4;--c-ink-2:#CFC3B5;--c-jade:#5FD3B0;--c-saffron-soft:#3D3212';
  for (const l of ['zh', 'en']) {
    const all = Object.keys(PIC).map((k) => `<figure><div>${PIC[k][l]}</div><figcaption>${k}</figcaption></figure>`).join('');
    await p.setViewportSize({ width: 1240, height: 900 });
    await p.setContent(`<style>body{margin:0;font:12px system-ui}.wall{display:flex;flex-wrap:wrap;gap:14px;padding:16px;align-items:flex-start}figure{margin:0}figcaption{opacity:.7;margin-top:4px}
      .light{background:#FBF5EC;color:#1D1915}.dark{background:#14110E;color:#F6EEE4;${darkVars}}</style>
      <div class="wall light">${all}</div><div class="wall dark">${all}</div>`);
    // overflow self-check: text beyond the picture's frame
    const bad = await p.evaluate(() => [...document.querySelectorAll('.light figure')].flatMap((f) => {
      const svg = f.querySelector('svg'), box = svg.getBoundingClientRect();
      return [...svg.querySelectorAll('text')].filter((t) => { const r = t.getBoundingClientRect(); return r.right > box.right - 22 || r.left < box.left + 20 || r.bottom > box.bottom; })
        .map((t) => f.querySelector('figcaption').textContent + ': ' + t.textContent);
    }));
    if (bad.length) console.log(`[${l}] text past frame:\n  ` + bad.join('\n  '));
    await p.screenshot({ path: path.join(D, `shots/pictures-${l}.png`), fullPage: true });
  }
  await b.close();
  console.log('PNGs and check sheets written.');
})();
